import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.BjkiRu3Q.js";const p=JSON.parse('{"title":"Payments and reconciliation","description":"","frontmatter":{},"headers":[],"relativePath":"plus/payments-and-reconciliation.md","filePath":"plus/payments-and-reconciliation.md"}'),r={name:"plus/payments-and-reconciliation.md"};function o(l,e,c,s,d,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="payments-and-reconciliation" tabindex="-1">Payments and reconciliation <a class="header-anchor" href="#payments-and-reconciliation" aria-label="Permalink to &quot;Payments and reconciliation&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>TransferBook+ v0.7.9 source-reviewed draft. Availability depends on the installed release, permissions and configuration; no commercial activation is asserted.</p></div><p>Inspect the payment and refund ledger and understand the distinction between recording money received and initiating a provider transaction.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Use an approved workspace, confirm your company and role, and use synthetic records for training.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><ol><li>Open Payments &amp; Billing and select the relevant reservation. Review the existing ledger and outstanding amount before recording anything.</li><li>For an authorized received payment, review Rail / Provider, Payment Kind (full, deposit, partial or balance), Amount (EUR) and Receipt / Reference Note. Never enter card numbers. Record only an actual, evidenced receipt.</li><li>If a provider transaction is uncertain, review Provider reconciliation and the available recovery or inspection controls rather than starting another charge. Refund requests require an authorized role and an audit reason.</li></ol><h2 id="verification-and-troubleshooting" tabindex="-1">Verification and troubleshooting <a class="header-anchor" href="#verification-and-troubleshooting" aria-label="Permalink to &quot;Verification and troubleshooting&quot;">​</a></h2><p>Provider options are not proof of enabled live checkout. Do not charge or refund real funds during training. A reservation tariff is not collected revenue; an uncertain payment must be reconciled before retrying.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="/plus/">Operator Manual</a></li><li><a href="/plus/reservations.html">Reservations</a></li><li><a href="/plus/dispatch-schedule.html">Dispatch schedule</a></li></ul><h2 id="v0-7-26-commercial-finance" tabindex="-1">v0.7.26 commercial finance <a class="header-anchor" href="#v0-7-26-commercial-finance" aria-label="Permalink to &quot;v0.7.26 commercial finance&quot;">​</a></h2><p>Partial cash collection and physical office handover have distinct records. Verify the receipt, original collecting chauffeur and actual cash before confirming custody; use the <a href="/plus/cash-management.html">Cash management guide</a>. Review supplier settlements separately using <a href="/plus/subcontractors.html">Subcontractors</a>. The Command Center Collected / Authorized figure includes authorizations and its Outstanding indicator is not an exact post-partial-payment balance; reconcile with individual records. External PSP activation remains separate from recording money. See <a href="/integrations/payment-api-setup.html">Payment gateway setup</a>.</p>',13)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
